  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert: returns ok for valid currencies', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert: EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 10000 cents EUR * 1.085 = 10850 cents USD
  assert.equal(result.value, 10850);
});

test('convert: EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 10000 cents EUR * 0.8425 = 8425 cents GBP
  assert.equal(result.value, 8425);
});

test('convert: returns same amount for EUR', () => {
  const result = convert(12345, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('convert: UNKNOWN_CURRENCY for invalid code', () => {
  const result = convert(100, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert: rounds result to whole cents', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 1 * 1.085 = 1.085, rounds to 1
  assert.equal(result.value, 1);
});

test('convert: handles large amounts', () => {
  const result = convert(100000000, 'USD');
  assert.equal(result.ok, true);
  // 100000000 * 1.085 = 108500000
  assert.equal(result.value, 108500000);
});

test('convert: handles negative amounts', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  // -10000 * 1.085 = -10850
  assert.equal(result.value, -10850);
});

test('formatMoney: EUR uses euro symbol', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney: USD uses dollar symbol', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney: GBP uses pound symbol', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney: formats with thousands separators', () => {
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney: formats small amounts with leading zero', () => {
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
});

test('formatMoney: handles negative amounts with sign', () => {
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
});

test('formatMoney: handles zero amount', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney: unknown currency defaults to euro symbol', () => {
  assert.equal(formatMoney(12345, 'XYZ'), '€123.45');
});

